// Manual runs explicitly start or resume the sending session.
return [
  {
    json: {
      runnerTriggerType: 'manual',
    },
  },
];

const staticData = $getWorkflowStaticData('global');
staticData.sendingEnabled = true;
staticData.nextBatchAllowedAt = null;

return [
  {
    json: {
      runnerTriggerType: 'webhook_start',
    },
  },
];

// Scheduled runs are one-minute checks. They only send when static data says a session is enabled and due.
return [
  {
    json: {
      runnerTriggerType: 'schedule',
    },
  },
];

const TIME_ZONE = 'America/New_York';
const FORCE_TEST_MODE = false;
const TEST_SUBJECT_PREFIX = '[N8N TEST]';
const TEST_DAILY_LIMIT = 2;
const TEST_MIN_BATCH_SIZE = 1;
const TEST_MAX_BATCH_SIZE = 2;
const TEST_DRAFT_SCAN_LIMIT = 100;
const DAILY_LIMIT = 300;
let MIN_BATCH_SIZE = 9;
let MAX_BATCH_SIZE = 18;
let MIN_EMAIL_DELAY_SECONDS = 8;
let MAX_EMAIL_DELAY_SECONDS = 25;
let MIN_BATCH_DELAY_MINUTES = 5;
let MAX_BATCH_DELAY_MINUTES = 7;

// Testing notes:
// - FORCE_TEST_MODE sends only drafts whose subject starts with TEST_SUBJECT_PREFIX.
// - Test mode uses TEST_DAILY_LIMIT and TEST_* batch sizing, then disables sending after one safe test batch.
// - Set FORCE_TEST_MODE back to false before production.
// - This workflow sends existing Gmail drafts through users.drafts.send and does not create, edit, or delete drafts manually.

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const triggerType = $json.runnerTriggerType || 'schedule';
const isStartTrigger = triggerType === 'manual' || triggerType === 'webhook_start';

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function getEasternDateKey(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const values = Object.fromEntries(
    parts
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value]),
  );

  return `${values.year}-${values.month}-${values.day}`;
}

const todayKey = getEasternDateKey(now);

// Reset sentToday when the Eastern date changes, but do not automatically start a new session.
if (staticData.date !== todayKey) {
  staticData.date = todayKey;
  staticData.sentToday = 0;
  staticData.currentBatchSentCount = 0;
}

if (isStartTrigger) {
  staticData.sendingEnabled = true;
  staticData.nextBatchAllowedAt = null;
}

const dailyLimit = FORCE_TEST_MODE ? TEST_DAILY_LIMIT : DAILY_LIMIT;
const minBatchSize = FORCE_TEST_MODE ? TEST_MIN_BATCH_SIZE : MIN_BATCH_SIZE;
const maxBatchSize = FORCE_TEST_MODE ? TEST_MAX_BATCH_SIZE : MAX_BATCH_SIZE;
const sentToday = Number(staticData.sentToday || 0);
const remainingToday = Math.max(dailyLimit - sentToday, 0);
const sendingEnabled = Boolean(staticData.sendingEnabled);
const nextBatchAllowedAt = staticData.nextBatchAllowedAt || null;
const nextBatchTime = nextBatchAllowedAt ? Date.parse(nextBatchAllowedAt) : 0;
const batchDue = isStartTrigger || !nextBatchAllowedAt || Number.isNaN(nextBatchTime) || now.getTime() >= nextBatchTime;

let allowed = false;
let reason = '';

if (sentToday >= dailyLimit) {
  staticData.sendingEnabled = false;
  allowed = false;
  reason = 'DAILY_LIMIT_REACHED';
} else if (!sendingEnabled) {
  allowed = false;
  reason = 'SENDING_DISABLED';
} else if (!batchDue) {
  allowed = false;
  reason = 'NOT_DUE_YET';
} else {
  allowed = true;
  reason = FORCE_TEST_MODE
    ? 'FORCE_TEST_MODE_ACTIVE'
    : (triggerType === 'webhook_start' ? 'WEBHOOK_SESSION_STARTED' : (triggerType === 'manual' ? 'MANUAL_SESSION_STARTED' : 'SCHEDULED_BATCH_DUE'));
}

const batchSize = allowed ? Math.min(randomInt(minBatchSize, maxBatchSize), remainingToday) : 0;
const listMaxResults = FORCE_TEST_MODE ? TEST_DRAFT_SCAN_LIMIT : batchSize;

if (allowed) {
  staticData.currentBatchSentCount = 0;
  staticData.currentBatchRequestedSize = batchSize;
  staticData.currentBatchSelectedDraftCount = 0;
  staticData.currentBatchForceTestMode = FORCE_TEST_MODE;

  // Reserve a temporary guard so the one-minute schedule cannot overlap the active batch.
  // Set Next Batch Time And Session State overwrites this after the batch finishes.
  const overlapGuardSeconds = (MAX_BATCH_SIZE * MAX_EMAIL_DELAY_SECONDS) + (MAX_BATCH_DELAY_MINUTES * 60) + 120;
  staticData.nextBatchAllowedAt = new Date(now.getTime() + overlapGuardSeconds * 1000).toISOString();
}

return [
  {
    json: {
      allowed,
      reason,
      todayKey,
      sentToday,
      dailyLimit,
      remainingToday,
      batchSize,
      listMaxResults,
      minEmailDelaySeconds: MIN_EMAIL_DELAY_SECONDS,
      maxEmailDelaySeconds: MAX_EMAIL_DELAY_SECONDS,
      minBatchDelayMinutes: MIN_BATCH_DELAY_MINUTES,
      maxBatchDelayMinutes: MAX_BATCH_DELAY_MINUTES,
      sendingEnabled: Boolean(staticData.sendingEnabled),
      nextBatchAllowedAt: staticData.nextBatchAllowedAt || null,
      forceTestMode: FORCE_TEST_MODE,
      testSubjectPrefix: TEST_SUBJECT_PREFIX,
      triggerType,
    },
  },
];

const config = $('Check Daily Limit And Runner State').item.json;
const staticData = $getWorkflowStaticData('global');
const drafts = Array.isArray($json.drafts) ? $json.drafts : [];
const draftsReturned = drafts.length;
const moreDraftsAvailable = Boolean($json.nextPageToken);

if (draftsReturned === 0) {
  staticData.currentBatchSelectedDraftCount = 0;
  console.log('No Gmail drafts returned. The sending session will be disabled.');
  return [
    {
      json: {
        hasDrafts: false,
        noDraftsRemaining: true,
        noDraftsReason: 'NO_DRAFTS_REMAINING',
        batchSize: config.batchSize,
        draftsReturned: 0,
        moreDraftsAvailable,
        dailyLimit: config.dailyLimit,
        minBatchDelayMinutes: config.minBatchDelayMinutes,
        maxBatchDelayMinutes: config.maxBatchDelayMinutes,
        forceTestMode: config.forceTestMode,
        testSubjectPrefix: config.testSubjectPrefix,
      },
    },
  ];
}

if (!config.forceTestMode) {
  staticData.currentBatchSelectedDraftCount = draftsReturned;
}

// users.drafts.list returns draft IDs and message IDs only. Test mode fetches metadata next before any draft can be sent.
return drafts
  .filter((draft) => draft && draft.id)
  .map((draft) => ({
    json: {
      hasDrafts: true,
      draftId: draft.id,
      messageId: draft.message?.id || null,
      batchSize: config.batchSize,
      draftsReturned,
      listedDraftsReturned: draftsReturned,
      moreDraftsAvailable,
      dailyLimit: config.dailyLimit,
      minEmailDelaySeconds: config.minEmailDelaySeconds,
      maxEmailDelaySeconds: config.maxEmailDelaySeconds,
      minBatchDelayMinutes: config.minBatchDelayMinutes,
      maxBatchDelayMinutes: config.maxBatchDelayMinutes,
      forceTestMode: config.forceTestMode,
      testSubjectPrefix: config.testSubjectPrefix,
    },
  }));

const config = $('Check Daily Limit And Runner State').item.json;
const staticData = $getWorkflowStaticData('global');
const inputItems = $input.all();
const testSubjectPrefix = config.testSubjectPrefix || '[N8N TEST]';
const batchSize = Number(config.batchSize || 0);
const moreDraftsAvailable = Boolean($('Normalize Draft Batch').first().json.moreDraftsAvailable);

function getSubject(headers) {
  if (!Array.isArray(headers)) {
    return '';
  }

  const header = headers.find((entry) => String(entry.name || '').toLowerCase() === 'subject');
  return header?.value || '';
}

const candidates = inputItems.map((item) => {
  const draft = item.json;
  const subject = getSubject(draft.message?.payload?.headers);

  return {
    draftId: draft.id,
    messageId: draft.message?.id || null,
    subject,
  };
});

const eligibleDrafts = candidates.filter((draft) => draft.subject.startsWith(testSubjectPrefix));
const selectedDrafts = eligibleDrafts.slice(0, batchSize);
staticData.currentBatchSelectedDraftCount = selectedDrafts.length;

const skipped = candidates
  .filter((draft) => !draft.subject.startsWith(testSubjectPrefix))
  .map((draft) => ({ draftId: draft.draftId, subject: draft.subject }));

if (skipped.length > 0) {
  console.log(JSON.stringify({
    level: 'info',
    message: 'FORCE_TEST_MODE skipped drafts without the required subject prefix.',
    testSubjectPrefix,
    skipped,
  }));
}

if (selectedDrafts.length === 0) {
  console.log(JSON.stringify({
    level: 'info',
    message: 'FORCE_TEST_MODE found no drafts with the required subject prefix. Nothing will be sent.',
    testSubjectPrefix,
  }));

  return [
    {
      json: {
        hasDrafts: false,
        noDraftsRemaining: true,
        noDraftsReason: 'NO_MATCHING_TEST_DRAFTS_REMAINING',
        batchSize,
        draftsReturned: 0,
        listedDraftsReturned: candidates.length,
        eligibleDraftsReturned: eligibleDrafts.length,
        moreDraftsAvailable,
        dailyLimit: config.dailyLimit,
        minBatchDelayMinutes: config.minBatchDelayMinutes,
        maxBatchDelayMinutes: config.maxBatchDelayMinutes,
        forceTestMode: true,
        testSubjectPrefix,
      },
    },
  ];
}

return selectedDrafts.map((draft) => ({
  json: {
    hasDrafts: true,
    draftId: draft.draftId,
    messageId: draft.messageId,
    subject: draft.subject,
    batchSize,
    draftsReturned: selectedDrafts.length,
    listedDraftsReturned: candidates.length,
    eligibleDraftsReturned: eligibleDrafts.length,
    moreDraftsAvailable,
    dailyLimit: config.dailyLimit,
    minEmailDelaySeconds: config.minEmailDelaySeconds,
    maxEmailDelaySeconds: config.maxEmailDelaySeconds,
    minBatchDelayMinutes: config.minBatchDelayMinutes,
    maxBatchDelayMinutes: config.maxBatchDelayMinutes,
    forceTestMode: true,
    testSubjectPrefix,
  },
}));

const staticData = $getWorkflowStaticData('global');
const errorPayload = $json.error || $json;
staticData.sendingEnabled = false;
staticData.lastGmailApiError = {
  timestamp: new Date().toISOString(),
  error: errorPayload,
};

console.log(JSON.stringify({
  level: 'error',
  message: 'Gmail API error. Automatic sending has been disabled.',
  error: errorPayload,
}));

return [
  {
    json: {
      sendingEnabled: false,
      reason: 'GMAIL_API_ERROR_SENDING_DISABLED',
      timestamp: new Date().toISOString(),
      error: errorPayload,
    },
  },
];

const draftItem = $('Loop Through Drafts').item.json;
const minDelay = Number(draftItem.minEmailDelaySeconds || 8);
const maxDelay = Number(draftItem.maxEmailDelaySeconds || 25);

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// users.drafts.send has already sent the existing draft. This only chooses the pause before the next draft in this batch.
return [
  {
    json: {
      draftId: draftItem.draftId,
      subject: draftItem.subject,
      sentMessageId: $json.id || null,
      delaySeconds: randomInt(minDelay, maxDelay),
      minEmailDelaySeconds: minDelay,
      maxEmailDelaySeconds: maxDelay,
    },
  },
];

const TIME_ZONE = 'America/New_York';
const staticData = $getWorkflowStaticData('global');
const draftItem = $('Loop Through Drafts').item.json;

function getEasternDateKey(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const values = Object.fromEntries(
    parts
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value]),
  );

  return `${values.year}-${values.month}-${values.day}`;
}

const todayKey = getEasternDateKey(new Date());

// Count only confirmed successful sends, and reset if a run crosses into a new Eastern date.
if (staticData.date !== todayKey) {
  staticData.date = todayKey;
  staticData.sentToday = 0;
}

staticData.sentToday = Number(staticData.sentToday || 0) + 1;
staticData.currentBatchSentCount = Number(staticData.currentBatchSentCount || 0) + 1;

return [
  {
    json: {
      sentToday: staticData.sentToday,
      sentDraftId: draftItem.draftId,
      subject: draftItem.subject,
      timestamp: new Date().toISOString(),
      batchSize: draftItem.batchSize,
      draftsReturned: draftItem.draftsReturned,
      listedDraftsReturned: draftItem.listedDraftsReturned,
      eligibleDraftsReturned: draftItem.eligibleDraftsReturned,
      moreDraftsAvailable: draftItem.moreDraftsAvailable,
      dailyLimit: draftItem.dailyLimit,
      minBatchDelayMinutes: draftItem.minBatchDelayMinutes,
      maxBatchDelayMinutes: draftItem.maxBatchDelayMinutes,
      forceTestMode: draftItem.forceTestMode,
      testSubjectPrefix: draftItem.testSubjectPrefix,
    },
  },
];

const TIME_ZONE = 'America/New_York';
const staticData = $getWorkflowStaticData('global');
const inputItems = $input.all().map((item) => item.json);
const firstItem = inputItems[0] || {};
const config = $('Check Daily Limit And Runner State').item.json;
const dailyLimit = Number(firstItem.dailyLimit || config.dailyLimit || 300);
const batchSize = Number(firstItem.batchSize || staticData.currentBatchRequestedSize || config.batchSize || 0);
const selectedDraftsCount = Number(firstItem.draftsReturned || staticData.currentBatchSelectedDraftCount || inputItems.length || 0);
const sentThisBatch = Number(staticData.currentBatchSentCount || 0);
const minBatchDelayMinutes = Number(firstItem.minBatchDelayMinutes || config.minBatchDelayMinutes || 5);
const maxBatchDelayMinutes = Number(firstItem.maxBatchDelayMinutes || config.maxBatchDelayMinutes || 7);
const forceTestMode = Boolean(firstItem.forceTestMode || config.forceTestMode);
const moreDraftsAvailable = firstItem.moreDraftsAvailable === true;

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function getEasternDateKey(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const values = Object.fromEntries(
    parts
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value]),
  );

  return `${values.year}-${values.month}-${values.day}`;
}

const todayKey = getEasternDateKey(new Date());

if (staticData.date !== todayKey) {
  staticData.date = todayKey;
  staticData.sentToday = 0;
}

const sentToday = Number(staticData.sentToday || 0);
let reason = '';
let nextBatchDelayMinutes = 0;
let nextBatchAllowedAt = staticData.nextBatchAllowedAt || null;

if (sentToday >= dailyLimit) {
  staticData.sendingEnabled = false;
  reason = 'DAILY_LIMIT_REACHED';
  nextBatchAllowedAt = null;
  staticData.nextBatchAllowedAt = null;
} else if (firstItem.noDraftsRemaining || selectedDraftsCount === 0 || sentThisBatch === 0) {
  staticData.sendingEnabled = false;
  reason = firstItem.noDraftsReason || 'NO_DRAFTS_REMAINING';
  nextBatchAllowedAt = null;
  staticData.nextBatchAllowedAt = null;
} else if (forceTestMode) {
  staticData.sendingEnabled = false;
  reason = 'FORCE_TEST_MODE_BATCH_COMPLETE';
  nextBatchAllowedAt = null;
  staticData.nextBatchAllowedAt = null;
} else if (selectedDraftsCount < batchSize || !moreDraftsAvailable) {
  staticData.sendingEnabled = false;
  reason = 'NO_DRAFTS_REMAINING';
  nextBatchAllowedAt = null;
  staticData.nextBatchAllowedAt = null;
} else {
  nextBatchDelayMinutes = randomInt(minBatchDelayMinutes, maxBatchDelayMinutes);
  nextBatchAllowedAt = new Date(Date.now() + nextBatchDelayMinutes * 60 * 1000).toISOString();
  staticData.sendingEnabled = true;
  staticData.nextBatchAllowedAt = nextBatchAllowedAt;
  reason = 'NEXT_BATCH_SCHEDULED';
}

return [
  {
    json: {
      sendingEnabled: Boolean(staticData.sendingEnabled),
      nextBatchAllowedAt,
      nextBatchDelayMinutes,
      sentToday,
      sentThisBatch,
      dailyLimit,
      selectedDraftsCount,
      batchSize,
      moreDraftsAvailable,
      reason,
    },
  },
];
